package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct {
	TrId     string
	TrIncome decimal.Decimal
}

var WsEofFlag string
var WsTax decimal.Decimal
var WsNet decimal.Decimal
var WsTotalTax decimal.Decimal
var WsCount int64
var WsIncEd string
var WsTaxEd string
var WsNetEd string
var WsTotalEd string

var taxFile *os.File
var taxScanner *bufio.Scanner
var TaxRecGlobal TaxRec
var inputDone bool

func formatEdited(value decimal.Decimal, pic string) string {
	dot := strings.Index(pic, ".")
	var picInt, picFrac string
	var scale int
	if dot >= 0 {
		picInt = pic[:dot]
		picFrac = pic[dot+1:]
		scale = len(picFrac)
	} else {
		picInt = pic
		picFrac = ""
		scale = 0
	}
	// integer slots
	digitSlots := 0
	digitTypes := []byte{}
	for i := 0; i < len(picInt); i++ {
		c := picInt[i]
		if c == 'Z' || c == '9' {
			digitSlots++
			digitTypes = append(digitTypes, c)
		}
	}
	// get integer and fractional strings from value
	// value is non-negative in this program; handle sign minimally
	neg := value.Sign() < 0
	if neg {
		value = value.Abs()
	}
	// ensure scale
	// Use StringFixed to get fractional part with exact scale
	var s string
	if scale > 0 {
		s = value.StringFixed(int32(scale))
	} else {
		s = value.StringFixed(0)
	}
	// s like "123.45" or "0.00"
	var intStr, fracStr string
	if scale > 0 {
		parts := strings.SplitN(s, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", scale)
		}
		// handle negative sign removed earlier
		if strings.HasPrefix(intStr, "-") {
			intStr = intStr[1:]
		}
	} else {
		intStr = s
		if strings.HasPrefix(intStr, "-") {
			intStr = intStr[1:]
		}
		fracStr = ""
	}
	// overflow: keep low-order digits
	if len(intStr) > digitSlots {
		intStr = intStr[len(intStr)-digitSlots:]
	}
	// pad to digitSlots with leading zeros
	padded := strings.Repeat("0", digitSlots-len(intStr)) + intStr

	// find first non-zero
	firstNonZero := -1
	for i := 0; i < digitSlots; i++ {
		if padded[i] != '0' {
			firstNonZero = i
			break
		}
	}
	if firstNonZero == -1 {
		// zero value: only last digit (mandatory 9) is shown
		firstNonZero = digitSlots - 1
	}

	// build integer part output
	var outInt strings.Builder
	digitIdx := 0
	shown := false
	for i := 0; i < len(picInt); i++ {
		c := picInt[i]
		if c == ',' {
			if shown {
				outInt.WriteByte(',')
			} else {
				outInt.WriteByte(' ')
			}
		} else { // Z or 9
			isShown := digitIdx >= firstNonZero
			if isShown {
				outInt.WriteByte(padded[digitIdx])
				shown = true
			} else {
				outInt.WriteByte(' ')
			}
			digitIdx++
		}
	}
	result := outInt.String()
	if scale > 0 {
		// ensure fracStr length
		if len(fracStr) < scale {
			fracStr = fracStr + strings.Repeat("0", scale-len(fracStr))
		} else if len(fracStr) > scale {
			fracStr = fracStr[:scale]
		}
		result = result + "." + fracStr
	}
	// COBOL edited fields are exactly len(pic) bytes
	// result length should already equal len(pic)
	if len(result) < len(pic) {
		result = strings.Repeat(" ", len(pic)-len(result)) + result
	} else if len(result) > len(pic) {
		result = result[len(result)-len(pic):]
	}
	return result
}

func moveToEditedInc(v decimal.Decimal) {
	WsIncEd = formatEdited(v, "ZZZ,ZZ9.99")
}
func moveToEditedTax(v decimal.Decimal) {
	WsTaxEd = formatEdited(v, "ZZZ,ZZ9.99")
}
func moveToEditedNet(v decimal.Decimal) {
	WsNetEd = formatEdited(v, "ZZZ,ZZ9.99")
}
func moveToEditedTotal(v decimal.Decimal) {
	WsTotalEd = formatEdited(v, "ZZ,ZZZ,ZZ9.99")
}

// helpers for COBOL numeric handling
func truncScale(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Truncate(scale)
}
func roundScale(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Round(scale)
}

func READPARA() {
	if taxScanner.Scan() {
		line := taxScanner.Text()
		// LINE SEQUENTIAL: if line shorter than record length pad spaces, longer truncate
		if len(line) < 13 {
			line = line + strings.Repeat(" ", 13-len(line))
		} else if len(line) > 13 {
			line = line[:13]
		}
		trId := line[0:5]
		trIncomeRaw := line[5:13]
		// PIC 9(6)V99 : digits only, implied decimal 2
		// trim spaces? but should be digits
		trimmed := strings.TrimSpace(trIncomeRaw)
		var inc decimal.Decimal
		if trimmed == "" {
			inc = decimal.NewFromInt(0)
		} else {
			// parse digits as integer
			// trIncomeRaw may contain spaces if padded
			// Remove spaces
			clean := strings.TrimSpace(trIncomeRaw)
			// If clean empty -> 0
			// It should be 8 digits
			// Use decimal
			// Build via NewFromString then shift?
			// Digits represent value with 2 implied decimals
			// So decimal.New(n, -2)
			var n int64
			fmt.Sscanf(clean, "%d", &n)
			// However clean may have leading zeros; Sscanf works
			// To avoid overflow for large, use decimal
			// Use decimal.NewFromString for n
			// Simpler: parse with decimal
			d, err := decimal.NewFromString(clean)
			if err != nil {
				d = decimal.NewFromInt(0)
			}
			inc = d.Shift(-2)
		}
		TaxRecGlobal.TrId = trId
		TaxRecGlobal.TrIncome = inc
	} else {
		inputDone = true
		WsEofFlag = "Y"
	}
}

func PROCESSPARA() {
	// IF TR-INCOME <= 10000.00
	limit1 := decimal.NewFromInt(10000)
	limit2 := decimal.NewFromInt(40000)
	rate10 := decimal.NewFromFloat(0.10)
	rate20 := decimal.NewFromFloat(0.20)
	rate30 := decimal.NewFromFloat(0.30)
	thousand := decimal.NewFromInt(1000)
	sevenThousand := decimal.NewFromInt(7000)
	tenThousand := decimal.NewFromInt(10000)
	fortyThousand := decimal.NewFromInt(40000)

	if TaxRecGlobal.TrIncome.Cmp(limit1) <= 0 {
		v := TaxRecGlobal.TrIncome.Mul(rate10)
		WsTax = truncScale(roundScale(v, 2), 2)
	} else {
		if TaxRecGlobal.TrIncome.Cmp(limit2) <= 0 {
			v := TaxRecGlobal.TrIncome.Sub(tenThousand).Mul(rate20).Add(thousand)
			WsTax = truncScale(roundScale(v, 2), 2)
		} else {
			v := TaxRecGlobal.TrIncome.Sub(fortyThousand).Mul(rate30).Add(sevenThousand)
			WsTax = truncScale(roundScale(v, 2), 2)
		}
	}
	WsNet = truncScale(TaxRecGlobal.TrIncome.Sub(WsTax), 2)
	WsTotalTax = truncScale(WsTotalTax.Add(WsTax), 2)
	WsCount++

	moveToEditedInc(TaxRecGlobal.TrIncome)
	moveToEditedTax(WsTax)
	moveToEditedNet(WsNet)
	// DISPLAY TR-ID " " WS-INC-ED " " WS-TAX-ED " " WS-NET-ED
	fmt.Printf("%s %s %s %s\n", TaxRecGlobal.TrId, WsIncEd, WsTaxEd, WsNetEd)

	READPARA()
}

func main() {
	WsEofFlag = "N"
	WsTax = decimal.NewFromInt(0)
	WsNet = decimal.NewFromInt(0)
	WsTotalTax = decimal.NewFromInt(0)
	WsCount = 0
	inputDone = false

	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	taxFile = f
	defer taxFile.Close()
	taxScanner = bufio.NewScanner(taxFile)
	// allow long lines
	taxScanner.Buffer(make([]byte, 4096), 4096)

	// MAIN-PARA
	// OPEN INPUT TAX-FILE
	// PERFORM READ-PARA
	READPARA()
	// PERFORM PROCESS-PARA UNTIL INPUT-DONE
	for !inputDone {
		PROCESSPARA()
	}
	// CLOSE TAX-FILE
	// MOVE WS-TOTAL-TAX TO WS-TOTAL-ED
	moveToEditedTotal(WsTotalTax)
	fmt.Printf("TAXPAYERS: %d TOTAL TAX: %s\n", WsCount, WsTotalEd)
}

